final case class OrderMessage(id: String, customerId: String, totalMinor: Long)
object OrderMessage {                                  // wire half: codecs only
  implicit val decoder: Decoder[OrderMessage] = Decoder.instance { c =>
    for { id <- c.downField("id").as[String]; cid <- c.downField("customer_id").as[String]
          t <- c.downField("total_minor").as[Long] } yield OrderMessage(id, cid, t)
  }
  implicit val encoder: Encoder[OrderMessage] = Encoder.instance(m =>
    Json.obj("id" -> m.id.asJson, "customer_id" -> m.customerId.asJson, "total_minor" -> m.totalMinor.asJson))
}
object OrderMessageMapper {                            // invoked by the endpoint
  def toMessage(o: Order): OrderMessage = OrderMessage(o.id, o.customer.id, o.total.minorUnits)
}
